<article class="product-card reveal"><a href="{{ route('product',$product) }}"><div class="product-thumb">@if($product->promotionIsActive())<span class="promo-badge">Promoção</span>@endif @if($product->images->first())@php($imagePath = $product->images->first()->path)<img src="{{ str_starts_with($imagePath, 'assets/') ? asset($imagePath) : asset('storage/'.$imagePath) }}" alt="{{ $product->images->first()->alt_text ?: $product->name }}">@else<div class="product-placeholder">TROPIKAL</div>@endif</div><div class="product-body"><span class="eyebrow">{{ $product->category->name ?? '' }}</span><h3>{{ $product->name }}</h3><p>{{ $product->excerpt }}</p>@php($startingPrice=$product->startingPrice())@if($product->compare_at_price && $product->promotionIsActive())<del>{{ number_format((float)$product->compare_at_price,2,',','.') }} €</del>@endif<strong>{{ $startingPrice!==null ? 'Desde '.number_format($startingPrice,2,',','.') . ' €' : 'Sob consulta' }}</strong>@if($startingPrice!==null)<small>Preço indicativo, sujeito a confirmação.</small>@endif</div></a></article>
